#ifndef MY_HW__MY_HW_HPP_
#define MY_HW__MY_HW_HPP_

#include <vector>
#include <string>

#include "hardware_interface/system_interface.hpp"
#include "hardware_interface/types/hardware_interface_return_values.hpp"
#include "hardware_interface/hardware_info.hpp"
#include "rclcpp/macros.hpp"
#include "rclcpp_lifecycle/state.hpp"
#include "my_hw/visibility_control.h"

namespace my_hw
{
class MyHardwareInterface : public hardware_interface::SystemInterface
{
public:
  RCLCPP_SHARED_PTR_DEFINITIONS(MyHardwareInterface)

  MY_HW_PUBLIC
  hardware_interface::CallbackReturn on_init(const hardware_interface::HardwareInfo & info) override;

  MY_HW_PUBLIC
  std::vector<hardware_interface::StateInterface> export_state_interfaces() override;

  MY_HW_PUBLIC
  std::vector<hardware_interface::CommandInterface> export_command_interfaces() override;

  MY_HW_PUBLIC
  hardware_interface::CallbackReturn on_activate(const rclcpp_lifecycle::State & previous_state) override;

  MY_HW_PUBLIC
  hardware_interface::CallbackReturn on_deactivate(const rclcpp_lifecycle::State & previous_state) override;

  MY_HW_PUBLIC
  hardware_interface::return_type read(const rclcpp::Time & time, const rclcpp::Duration & period) override;

  MY_HW_PUBLIC
  hardware_interface::return_type write(const rclcpp::Time & time, const rclcpp::Duration & period) override;

private:
  std::vector<double> hw_position_commands_;
  std::vector<double> hw_position_states_;
  std::vector<double> hw_velocity_states_;
};

}  // namespace my_hw

#endif  // MY_HW__MY_HW_HPP_

