  const rclcpp_lifecycle::State & /*previous_state*/)
{
  // Avoid a jump at start-up: seed each position command with the current state,
  // and start with zero velocity.
  for (const hardware_interface::ComponentInfo & joint : info_.joints)
  {
    const double position = get_state(joint.name + "/" + hardware_interface::HW_IF_POSITION);
    set_command(joint.name + "/" + hardware_interface::HW_IF_POSITION, position);
    set_state(joint.name + "/" + hardware_interface::HW_IF_VELOCITY, 0.0);
  }

  RCLCPP_INFO(get_logger(), "MyHardwareInterface activated.");
  return hardware_interface::CallbackReturn::SUCCESS;
}

