#include "my_hw/my_hw.hpp"

#include "hardware_interface/types/hardware_interface_type_values.hpp"

namespace my_hw
{

hardware_interface::CallbackReturn MyHardwareInterface::on_init(
  const hardware_interface::HardwareComponentInterfaceParams & params)
{
  if (
    hardware_interface::SystemInterface::on_init(params) !=
    hardware_interface::CallbackReturn::SUCCESS)
  {
    return hardware_interface::CallbackReturn::ERROR;
  }

  for (const hardware_interface::ComponentInfo & joint : info_.joints)
  {
    if (joint.command_interfaces.size() != 1)
    {
      RCLCPP_FATAL(
        get_logger(), "Joint '%s' has %zu command interfaces found. 1 expected.",
        joint.name.c_str(), joint.command_interfaces.size());
      return hardware_interface::CallbackReturn::ERROR;
    }

    if (joint.command_interfaces[0].name != hardware_interface::HW_IF_POSITION)
    {
      RCLCPP_FATAL(
        get_logger(), "Joint '%s' has %s command interface found. '%s' expected.",
        joint.name.c_str(), joint.command_interfaces[0].name.c_str(),
        hardware_interface::HW_IF_POSITION);
      return hardware_interface::CallbackReturn::ERROR;
    }

    if (joint.state_interfaces.size() != 2)
    {
      RCLCPP_FATAL(
        get_logger(), "Joint '%s' has %zu state interfaces found. 2 expected.",
        joint.name.c_str(), joint.state_interfaces.size());
      return hardware_interface::CallbackReturn::ERROR;
    }

    if (joint.state_interfaces[0].name != hardware_interface::HW_IF_POSITION)
    {
      RCLCPP_FATAL(
        get_logger(), "Joint '%s' has '%s' as first state interface. '%s' expected.",
        joint.name.c_str(), joint.state_interfaces[0].name.c_str(),
        hardware_interface::HW_IF_POSITION);
      return hardware_interface::CallbackReturn::ERROR;
    }

    if (joint.state_interfaces[1].name != hardware_interface::HW_IF_VELOCITY)
    {
      RCLCPP_FATAL(
        get_logger(), "Joint '%s' has '%s' as second state interface. '%s' expected.",
        joint.name.c_str(), joint.state_interfaces[1].name.c_str(),
        hardware_interface::HW_IF_VELOCITY);
      return hardware_interface::CallbackReturn::ERROR;
    }
  }

  return hardware_interface::CallbackReturn::SUCCESS;
}

hardware_interface::CallbackReturn MyHardwareInterface::on_activate(
  const rclcpp_lifecycle::State & /*previous_state*/)
{
  // Avoid a jump at start-up: seed each position command with the current state,
  // and start with zero velocity.
  for (const hardware_interface::ComponentInfo & joint : info_.joints)
  {
    const double position = get_state(joint.name + "/" + hardware_interface::HW_IF_POSITION);
    set_command(joint.name + "/" + hardware_interface::HW_IF_POSITION, position);
    set_state(joint.name + "/" + hardware_interface::HW_IF_VELOCITY, 0.0);
  }

  RCLCPP_INFO(get_logger(), "MyHardwareInterface activated.");
  return hardware_interface::CallbackReturn::SUCCESS;
}

hardware_interface::CallbackReturn MyHardwareInterface::on_deactivate(
  const rclcpp_lifecycle::State & /*previous_state*/)
{
  RCLCPP_INFO(get_logger(), "MyHardwareInterface deactivated.");
  return hardware_interface::CallbackReturn::SUCCESS;
}

hardware_interface::return_type MyHardwareInterface::read(
  const rclcpp::Time & /*time*/, const rclcpp::Duration & /*period*/)
{
  // No physical hardware to poll: state is updated directly in write() below.
  return hardware_interface::return_type::OK;
}

hardware_interface::return_type MyHardwareInterface::write(
  const rclcpp::Time & /*time*/, const rclcpp::Duration & period)
{
  const double dt = period.seconds();

  for (const hardware_interface::ComponentInfo & joint : info_.joints)
  {
    const std::string position_state = joint.name + "/" + hardware_interface::HW_IF_POSITION;
    const std::string velocity_state = joint.name + "/" + hardware_interface::HW_IF_VELOCITY;
    const std::string position_command = joint.name + "/" + hardware_interface::HW_IF_POSITION;

    const double previous_position = get_state(position_state);
    const double commanded_position = get_command(position_command);

    // Integrate the commanded position into the reported state so a command
    // is reflected back through the state interface.
    if (dt > 0.0)
    {
      set_state(velocity_state, (commanded_position - previous_position) / dt);
    }
    set_state(position_state, commanded_position);
  }

  return hardware_interface::return_type::OK;
}

}  // namespace my_hw

#include "pluginlib/class_list_macros.hpp"
PLUGINLIB_EXPORT_CLASS(my_hw::MyHardwareInterface, hardware_interface::SystemInterface)
